bool convert(const char*const*g,size_t r,char*out){if(r%4)return false;if(!r){*out=0;return true;}size_t c=strlen(g[0]);if(c%3)return false;for(size_t i=0;i<r;i++)if(strlen(g[i])!=c)return false;const char*d[]={" _ | ||_|   ","     |  |   "," _  _||_    "," _  _| _|   ","   |_|  |   "," _ |_  _|   "," _ |_ |_|   "," _   |  |   "," _ |_||_|   "," _ |_| _|   "};for(size_t y=0;y<r;y+=4){if(y)*out++=',';for(size_t x=0;x<c;x+=3){char s[13];for(int k=0;k<4;k++)memcpy(s+3*k,g[y+k]+x,3);s[12]=0;char digit='?';for(int k=0;k<10;k++)if(!strcmp(s,d[k]))digit=(char)('0'+k);*out++=digit;}}*out=0;return true;}

